CREATE TABLE IF NOT EXISTS digest_subscriptions(user_id text PRIMARY KEY,email text NOT NULL,mode text NOT NULL CHECK(mode IN ('matching','all')),enabled boolean NOT NULL DEFAULT false,suppressed boolean NOT NULL DEFAULT false,generation integer NOT NULL DEFAULT 1,boundary bigint NOT NULL DEFAULT 0,activated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS digest_campaigns(publication_day text PRIMARY KEY,cutoff bigint NOT NULL,last_user text NOT NULL DEFAULT '',complete boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS email_deliveries(id uuid PRIMARY KEY,user_id text NOT NULL REFERENCES digest_subscriptions(user_id),publication_day text NOT NULL,generation integer NOT NULL,recipient text NOT NULL,mode text NOT NULL,jobs jsonb NOT NULL,body jsonb NOT NULL,unsubscribe_hash text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),first_attempt_at timestamptz,lease_until timestamptz,claim_id uuid,provider_id text UNIQUE,last_error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,publication_day));
CREATE INDEX IF NOT EXISTS digest_queue_due ON email_deliveries(status,next_attempt_at);
CREATE TABLE IF NOT EXISTS email_webhook_receipts(id text PRIMARY KEY,received_at timestamptz NOT NULL DEFAULT now());
